package com.itb.inf2dm.absencemanager.services; import java.util.*;import org.springframework.beans.factory.annotation.*;import org.springframework.stereotype.*;import com.itb.inf2dm.absencemanager.model.entity.TurmaAluno;import com.itb.inf2dm.absencemanager.model.repository.TurmaAlunoRepository; @Service public class TurmaAlunoService{ @Autowired private TurmaAlunoRepository repo; public List<TurmaAluno> findAll(){return repo.findAll();} public TurmaAluno findById(Long id){return repo.findById(id).orElseThrow();} public TurmaAluno create(TurmaAluno t){return repo.save(t);} public void delete(Long id){repo.deleteById(id);} }